import{_ as s,o as a,c as i,a3 as l}from"./chunks/framework.BL7OzMv1.js";const r="/BD1A26/assets/installateur.Cl4ipfRc.png",o="/BD1A26/assets/service.u4NR3YiA.png",t="/BD1A26/assets/path.Do7H_dAU.png",n="/BD1A26/assets/installateur-dbeaver.BV4Of9w2.png",d="/BD1A26/assets/nouvelle-connexion.zDMiIrLa.png",c="/BD1A26/assets/connexion-mariadb.hdDbLO89.png",u="/BD1A26/assets/options-connexion-mariadb.BcBlWbd4.png",p="/BD1A26/assets/drivers.BDjOkRUs.png",b="/BD1A26/assets/navigateur-bd.qyxsOVqX.png",g="/BD1A26/assets/new-db.CFSGEsE0.png",m="/BD1A26/assets/new-db-settings.DnL5vpEQ.png",h="/BD1A26/assets/bd-lab01.BjqL8CN0.png",v="/BD1A26/assets/new-db-code.BgAu3YKb.png",k="/BD1A26/assets/execute.DXTW55Gx.png",B="/BD1A26/assets/refresh.Rz9jOjz9.png",_="/BD1A26/assets/post-refresh.BTdctCrF.png",z=JSON.parse('{"title":"Lab — Installation et création de la base de données","description":"","frontmatter":{"title":"Lab — Installation et création de la base de données"},"headers":[],"relativePath":"labs/lab01-installations.md","filePath":"labs/lab01-installations.md"}'),D={name:"labs/lab01-installations.md"};function C(x,e,f,q,y,A){return a(),i("div",null,[...e[0]||(e[0]=[l('<h1 id="🧪-laboratoire-01-—-installation-et-creation-de-la-base-de-donnees" tabindex="-1">🧪 Laboratoire 01 — Installation et création de la base de données <a class="header-anchor" href="#🧪-laboratoire-01-—-installation-et-creation-de-la-base-de-donnees" aria-label="Permalink to &quot;🧪 Laboratoire 01 — Installation et création de la base de données&quot;">​</a></h1><div class="bg-blue-50 border border-blue-200 text-blue-900 rounded-lg p-4"><strong>Dans ce laboratoire, vous allez :</strong><br><ol><li>Installer la base de données MariaDB</li><li>Installer le client DBeaver</li><li>Créer une nouvelle connexion MariaDB</li><li>Créer une nouvelle base de données</li></ol></div><h2 id="prerequis" tabindex="-1">Prérequis <a class="header-anchor" href="#prerequis" aria-label="Permalink to &quot;Prérequis&quot;">​</a></h2><div class="bg-yellow-50 border border-yellow-200 text-yellow-900 rounded-lg p-4"><ul><li>Windows (instructions testées sur Windows 11)</li><li>Accès administrateur pour installer des programmes</li></ul></div><h2 id="_1-installer-mariadb" tabindex="-1">1. Installer MariaDB <a class="header-anchor" href="#_1-installer-mariadb" aria-label="Permalink to &quot;1. Installer MariaDB&quot;">​</a></h2><ol><li><p>Téléchargement</p><ul><li>Rendez-vous sur <a href="https://mariadb.org/download/" target="_blank" rel="noreferrer">https://mariadb.org/download/</a> et téléchargez le paquet <strong>MSI</strong> pour Windows. <img class="img-bordered w-xs" src="'+r+'" alt="installateur"></li></ul></li><li><p>Installation via l&#39;installateur</p><ul><li>Lancez le fichier <code>.msi</code> téléchargé et suivez l&#39;assistant.</li><li>Composants : laissez les valeurs par défaut (<code>Database instance</code> et <code>Client Programs</code>). L&#39;outil <code>HeidiSQL</code> est optionnel — nous utiliserons DBeaver.</li><li>Mot de passe : choisissez un mot de passe pour l&#39;utilisateur <code>root</code> (superutilisateur).</li><li>Cochez l&#39;option <strong>Use UTF8 as default server&#39;s character set</strong>.</li><li>Nom du service : <code>MariaDB</code> (par défaut).</li><li>Port : <code>3306</code> (par défaut).</li></ul></li><li><p>Vérifier le service MariaDB</p><ul><li>Appuyer sur la touche <code>Win + R</code></li><li>Entrer <code>services.msc</code></li><li>Trouver <code>MariaDB</code><ul><li><img class="img-bordered w-s" src="'+o+'" alt="service"></li><li>Normalement, le service devrait être lancé et avoir un type de démarrage automatique.</li><li>Dans le cas contraire, vous pouvez le corriger via clic-droit et propriétés.</li></ul></li></ul></li><li><p>Vérifier que <code>mariadb</code> est accessible dans le PATH</p></li></ol><p>Dans certaines situations, vous utiliserez le client <strong>mariadb</strong> en ligne de commande.<br> Il doit donc être accessible via le <strong>PATH de Windows</strong>.</p><ol><li>Ouvrez <strong>Invite de commandes</strong> ou <strong>PowerShell</strong></li><li>Entrez la commande suivante :</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mariadb</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span></code></pre></div><ul><li>Si une version de MariaDB s’affiche, tout est correct.</li><li>Si la commande est introuvable, le client n’est pas dans le PATH.</li></ul><blockquote><p>La commande <code>mysql --version</code> fonctionne aussi : c&#39;est l&#39;ancien nom du même client, conservé par MariaDB pour des raisons de compatibilité.</p></blockquote><details id="ajouter-au-path" class="border border-gray-300 rounded-md p-4 my-4 bg-yellow-50 text-gray-800"><summary class="cursor-pointer font-semibold"> Ajouter le client MariaDB au PATH (si nécessaire) </summary><div class="mt-4 space-y-3"><ul><li>Appuyer sur WIN / START</li><li>Taper envi et cliquer sur <code>Modifier les variables d’environnement système</code></li><li>Cliquer sur <strong>Variables d’environnement</strong></li><li>Dans <strong>Variables système</strong>, sélectionner <code>Path</code></li><li>Cliquer sur <strong>Nouveau</strong></li><li>Ajouter le dossier <code>bin</code> où est installé MariaDB</li></ul><p>Emplacement habituel (le numéro de version peut différer) :</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">C:\\Program</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Files</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\M</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">ariaDB</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 11.8</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\b</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">in</span></span></code></pre></div><img class="img-bordered mt-2" src="'+t+'" alt="PATH"><blockquote><p>L&#39;image est petite? Faites un clic-droit et <code>Ouvrir l&#39;image dans un nouvel onglet</code></p></blockquote></div></details><h2 id="_2-installer-dbeaver" tabindex="-1">2. Installer DBeaver <a class="header-anchor" href="#_2-installer-dbeaver" aria-label="Permalink to &quot;2. Installer DBeaver&quot;">​</a></h2><p>DBeaver est un logiciel de gestion de base de données. Il servira à créer et à gérer votre base de données MariaDB.</p><ol><li><p>Téléchargement</p><ul><li>Rendez-vous sur <a href="https://dbeaver.io/download/" target="_blank" rel="noreferrer">https://dbeaver.io/download/</a> et téléchargez l&#39;installateur</li><li><img class="img-bordered w-xs" src="'+n+'" alt="installateur dbeaver"></li></ul></li><li><p>Installation via l&#39;installateur</p><ul><li>Lancez le fichier <code>.exe</code> téléchargé et suivez l&#39;assistant.</li><li>Conservez les paramètres par défaut.</li></ul></li></ol><h2 id="_3-creer-une-nouvelle-connexion" tabindex="-1">3. Créer une nouvelle connexion <a class="header-anchor" href="#_3-creer-une-nouvelle-connexion" aria-label="Permalink to &quot;3. Créer une nouvelle connexion&quot;">​</a></h2><p>À cette étape, vous allez connecter <strong>DBeaver</strong> à votre service <strong>MariaDB</strong>.</p><ol><li><p>Ouvrir DBeaver.</p></li><li><p>En haut à gauche, cliquer sur <code>nouvelle connexion</code>.</p><ul><li><img class="img-bordered w-s" src="'+d+'" alt="nouvelle connexion"></li></ul></li><li><p>Sélectionner la base de données MariaDB.</p><ul><li>Attention : DBeaver propose aussi <code>MySQL</code>. Choisissez bien <strong>MariaDB</strong>.</li><li><img class="img-bordered w-s" src="'+c+'" alt="connexion mariadb"></li></ul></li><li><p>Confirmer les options de connexion.</p><ul><li>Serveur : <code>localhost</code> — Port : <code>3306</code>.</li><li>Utilisateur : <code>root</code>.</li><li>Entrez le mot de passe que vous avez sélectionné pour l&#39;utilisateur <code>root</code> lors de l&#39;installation de MariaDB.</li><li>Activer l&#39;option <strong>Show all databases</strong> pour voir toutes les bases de données.</li><li><img class="img-bordered w-s" src="'+u+'" alt="options connexion"></li></ul></li><li><p>Installer les pilotes.</p><ul><li>Après avoir créé la nouvelle connexion, DBeaver vous proposera de télécharger les pilotes pour MariaDB.</li><li>Cliquer sur télécharger.</li><li><img class="img-bordered w-xs" src="'+p+'" alt="drivers"></li></ul></li></ol><h2 id="_4-creer-une-base-de-donnees" tabindex="-1">4. Créer une base de données <a class="header-anchor" href="#_4-creer-une-base-de-donnees" aria-label="Permalink to &quot;4. Créer une base de données&quot;">​</a></h2><ol><li><p>La section de gauche de l&#39;interface de DBeaver correspond au navigateur de connexions et de bases de données. Vous devriez voir apparaître votre connexion à MariaDB que vous venez de créer.</p><ul><li><img class="img-bordered w-s" src="'+b+'" alt="navigateur"></li></ul></li><li><p>Clic-droit sur <code>Bases de données</code> et cliquer sur <code>Créer base de données</code></p><ul><li><img class="img-bordered w-s" src="'+g+'" alt="new db"></li></ul></li><li><p>Nommer la base de données <code>lab01</code> et conserver le jeu de caractères <code>utf8mb4</code></p><ul><li><img class="img-bordered w-3xs" src="'+m+'" alt="new db settings"></li></ul></li><li><p>Voilà, vous avez maintenant créé votre première base de données. Vous pouvez la conserver ou la supprimer avec clic-droit + supprimer (attention cette action est irréversible --&gt; à ne pas faire pendant vos tps.)</p><ul><li><img class="img-bordered w-s" src="'+h+'" alt="bd lab01"></li></ul></li></ol><h3 id="_4-1-creation-de-la-base-de-donnees-par-code-sql" tabindex="-1">4.1 Création de la base de données par code SQL <a class="header-anchor" href="#_4-1-creation-de-la-base-de-donnees-par-code-sql" aria-label="Permalink to &quot;4.1 Création de la base de données par code SQL&quot;">​</a></h3><div class="bg-green-50 border-green-500 p-4 mt-4 rounded-s text-green-800"><p>Cette étape vous montre comment créer exactement la même base de données mais <strong>avec une commande SQL</strong>, au lieu d’utiliser l’interface de DBeaver. Nous verrons cela plus en détail dans le module 2.</p><ol><li><p>Vous devez d&#39;abord ouvrir un <strong>nouvel éditeur SQL</strong> sur votre connexion MariaDB (voir l&#39;image ci-dessous): <img class="img-bordered w-s" src="'+v+'" alt="new db code"></p></li><li><p>Vous pouvez exécuter cette commande dans l’éditeur SQL de DBeaver.</p><div class="bg-gray-50 border-l-4 border-blue-500 p-4 rounded-s"><b>Commande SQL :</b><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">create</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> database</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> lab01</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div></div><img class="img-bordered w-s mt-4" src="'+k+'" alt="execute"></li><li><p>Pour voir votre <strong>nouvelle base de données apparaître</strong>, vous devez rafraîchir dans l&#39;explorateur à gauche: <img class="img-bordered w-xs mt-4" src="'+B+'" alt="refresh"><img class="img-bordered w-2xs mt-4" src="'+_+'" alt="post-refresh"></p></li><li><p>Créer une base de données ne veut pas dire qu&#39;on y travaille. Pour <strong>choisir la base active</strong> dans l&#39;éditeur SQL, on utilise la commande <code>use</code> :</p><div class="bg-gray-50 border-l-4 border-blue-500 p-4 rounded-s"><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">use</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> lab01;</span></span></code></pre></div></div><p>Toutes les commandes qui suivent s&#39;appliqueront alors à <code>lab01</code>.</p></li></ol></div>',22)])])}const F=s(D,[["render",C]]);export{z as __pageData,F as default};
